sys_ui_page.client_script:
// Function to show a warning about the update feature limitation
// This function replaces the old updateIncidents()
function updateCommentsWarning() {
    alert('Due to browser security, records selected within the embedded list cannot be directly accessed for updates from this page. This functionality requires a different approach, such as a List UI Action on the native Incident list or a Service Portal widget.');
}

// Function to filter the iframe based on keyword
function filterIframeList() {
    var searchKeyword = document.getElementById('searchInput').value;
    var iframe = document.getElementById('incidentListIframe');

    var baseURL = 'incident_list.do?sysparm_view=default';
    var encodedQuery = '';

    if (searchKeyword) {
        // Construct an encoded query to search across multiple fields for the keyword
        // Using LIKE for broader search, and ^OR for "any of these fields"
        encodedQuery = 'commentsLIKE' + encodeURIComponent(searchKeyword) +
                       '^ORwork_notesLIKE' + encodeURIComponent(searchKeyword) +
                       '^ORshort_descriptionLIKE' + encodeURIComponent(searchKeyword);
    }

    var finalQuery = 'ORDERBYsys_created_onDESC'; // Default sort
    if (encodedQuery) {
        finalQuery += '^' + encodedQuery; // Combine with keyword query
    }

    // Set the iframe's src to load the filtered list
    iframe.src = baseURL + '&sysparm_query=' + encodeURIComponent(finalQuery);
}

// Function to clear the filter in the iframe
function clearIframeFilter() {
    document.getElementById('searchInput').value = ''; 
    var iframe = document.getElementById('incidentListIframe');
    iframe.src = 'incident_list.do?sysparm_view=default&sysparm_query=ORDERBYsys_created_onDESC'; // Reset to default view
}

// --- IMPORTANT: Remove any other old functions from previous iterations here ---
// If you have functions like refreshIncidentList, searchIncidents (that populated a custom table),
// toggleAllCheckboxes, openNativeFilterBuilder, updateFilterDisplay, etc.,
// please ensure they are removed from your Client Script. They are not used in this iframe approach.
